<x-table :rows="$counts" caption="Stock counts" :empty-title="$search?'No matching counts':'No stock counts yet'" empty-description="Create a count, add physical quantities, and post the reconciliation."><x-slot:toolbar><div class="unit-toolbar"><button class="btn btn-sm btn-success" data-bs-toggle="offcanvas" data-bs-target="#createStockCountDrawer" aria-label="Create stock count"><i class="bi bi-plus-lg"></i></button><x-search-filter :action="route('stock-counts.index')" search-label="Search stock counts" search-placeholder="Search count number or notes" search-container-class="unit-search-field" class="unit-search-filter" data-live-search="true" data-live-target="#stock-count-results" data-live-delay="300" submit-label="Filter" :search-value="$search" :filters="[['name'=>'status','label'=>'Status','value'=>'all','resetValue'=>'all','placeholder'=>'Show all','showPlaceholderOption'=>false,'options'=>['all'=>'Show all','draft'=>'Draft','posted'=>'Posted','cancelled'=>'Cancelled'],'class'=>'unit-status-filter']]" /></div></x-slot:toolbar><x-slot:head><tr><th>Count</th><th>Location</th><th>Date</th><th>Status</th><th class="text-end">Lines</th><th class="text-end">Actions</th></tr></x-slot:head><x-slot:body>@foreach($counts as $count)<tr><td>{{ $count->count_number }}</td><td>{{ $count->stockLocation?->name }}</td><td>{{ $count->count_date?->format('M j, Y') }}</td><td>{{ ucfirst($count->status) }}</td><td class="text-end">{{ $count->items_count }}</td><td class="text-end text-nowrap"><a class="btn btn-sm btn-outline-secondary" href="{{ route('stock-count-items.index',['stock_count_id'=>$count->id]) }}" aria-label="Manage count lines"><i class="bi bi-list-ul"></i></a>@if($count->status==='draft')<button class="btn btn-sm btn-outline-primary" data-bs-toggle="offcanvas" data-bs-target="#editStockCountDrawer-{{ $count->id }}" aria-label="Edit count"><i class="bi bi-pencil"></i></button><form class="d-inline" method="POST" action="{{ route('stock-counts.post',$count) }}"